<template>
  <div class="exhibition-audio" :class="{ 'is-enabled': enabled }">
    <button type="button" :disabled="!shareId" :aria-pressed="enabled" :aria-label="enabled ? 'Pause audio guide' : 'Start audio guide'" :title="error ? 'Audio is unavailable. Try again.' : enabled ? 'Audio guide on' : 'Listen as you explore'" @click="toggle">
      <svg class="exhibition-audio-symbol" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 11V9a6 6 0 0 1 12 0v2M4 10H3v6h3v-6Zm12 0h1v6h-3v-6Z"/></svg>
      <span>Audio guide</span>
      <span class="exhibition-audio-state" :class="{ 'is-waiting': waiting }" aria-hidden="true"><svg v-if="enabled" viewBox="0 0 12 12"><path v-if="playing" d="M4 2v8m4-8v8"/><circle v-else cx="6" cy="6" r="2" /></svg><svg v-else viewBox="0 0 12 12"><path d="m4 2 6 4-6 4Z" /></svg></span>
    </button>
    <button v-if="enabled && cue && !busy && arrived && !travelling" class="exhibition-audio-replay" type="button" aria-label="Replay this passage" title="Replay this passage" @click="replay"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5 6a6 6 0 1 1-1 7M5 2v5H1" /></svg></button>
    <button v-if="hasOtherPassage" class="exhibition-audio-here" type="button" title="Start the passage in view" @click="listenHere"><span class="exhibition-audio-here-label">Listen here</span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10m-4-4 4 4-4 4" /></svg></button>
    <span v-if="error" class="exhibition-audio-error" role="status">Audio unavailable</span>
    <audio ref="audio" preload="none" crossorigin="anonymous" @waiting="waiting = enabled && !busy" @playing="waiting = false; playing = true; reportProgress()" @pause="playing = false; reportProgress()" @loadedmetadata="restoreTime" @durationchange="reportProgress" @timeupdate="reportProgress" @ended="ended" @error="failed" />
  </div>
</template>

<script>
import { askEndpoints } from '../../utils/askSite';
import { ExhibitionListeningHistory } from '../../utils/exhibitionGuideAudio';
import { exhibitionSpeechWordAt, exhibitionSpeechProgress } from '../../utils/exhibitionSpokenText';

export default {
  props: { cue: { type: Object, default: null }, text: { type:String, default:'' }, busy: Boolean, travelling: Boolean, language: { type: String, default: '' }, shareId: { type: String, default: '' } },
  emits: ['complete','progress'],
  data: () => ({ enabled: false, playing: false, waiting: false, error: false, loadedKey: '', arrived: true }),
  computed: {
    playbackKey() { return `${this.shareId}/${this.language}/${this.cue?.key || ''}`; },
    hasOtherPassage() { return Boolean(this.enabled && this.loadedKey && this.cue && this.loadedKey !== this.playbackKey && !this.busy && !this.travelling && this.arrived); },
  },
  mounted() {
    this._history = new ExhibitionListeningHistory();
    if (this.travelling) this.arrived = false;
    this._otherAudio = event => { if (event.detail !== this) { this.enabled = false; this.pause(); } };
    this._visibility = () => this.sync();
    window.addEventListener('view-summary-play', this._otherAudio);
    document.addEventListener('visibilitychange', this._visibility);
  },
  beforeUnmount() { clearTimeout(this._arrivalTimer); window.removeEventListener('view-summary-play', this._otherAudio); document.removeEventListener('visibilitychange', this._visibility); this.pause(); this.$refs.audio?.removeAttribute('src'); this.$refs.audio?.load(); },
  watch: {
    playbackKey() { this.sync(); },
    language() { this.pause(); this.loadedKey = ''; this.sync({ focused: true }); },
    shareId() { this.pause(); this.loadedKey = ''; this._history = new ExhibitionListeningHistory(); this.sync({ focused: true }); },
    busy(next) { if (!next) this.sync(); },
    travelling(next) { this.settleNarration(next); },
  },
  methods: {
    settleNarration(travelling) {
      clearTimeout(this._arrivalTimer);
      this.arrived = false;
      if (travelling) {
        // Keep an ongoing passage audible. A recording still waiting to start
        // belongs to the destination and must wait for the visitor to arrive.
        if (this.waiting && !this.playing) { this.pause(); this.loadedKey = ''; this._loadedCue = null; }
        return;
      }
      this._arrivalTimer = setTimeout(() => { this.arrived = true; this.sync(); }, 250);
    },
    toggle() {
      this.enabled = !this.enabled;
      if (!this.enabled) { this.pause(); this.$emit('progress',{key:'',wordIndex:-1,playing:false}); }
      else if (this.loadedKey === this.playbackKey && this._history.progress(this.cue, this.language).complete) this.replay();
      else this.sync();
    },
    replay() {
      this.pause();
      this.enabled = true;
      this._history.replay(this._loadedCue || this.cue, this._loadedLanguage ?? this.language);
      if (this.$refs.audio) this.$refs.audio.currentTime = 0;
      this.sync();
    },
    listenHere() {
      this.pause();
      this.enabled = true;
      this._history.replay(this.cue, this.language);
      this.sync({ focused: true });
    },
    pause() {
      this._token = (this._token || 0) + 1;
      const audio = this.$refs.audio;
      if (this._loadedCue && audio) this._history.remember(this._loadedCue, this._loadedLanguage, audio.currentTime || 0);
      audio?.pause(); this.playing = false; this.waiting = false;
      window.dispatchEvent(new CustomEvent('view-summary-pause', { detail: this }));
    },
    restoreTime() {
      const audio = this.$refs.audio;
      const time = this._history.progress(this._loadedCue, this._loadedLanguage).time;
      if (time > 0 && Number.isFinite(audio.duration)) audio.currentTime = Math.min(time, Math.max(0, audio.duration - .05));
      this.reportProgress();
    },
    reportProgress() {
      const audio=this.$refs.audio;
      const progress=exhibitionSpeechProgress(this._loadedText, audio?.currentTime, audio?.duration, this._loadedLanguage);
      this.$emit('progress',{key:this._loadedCue?.key||'',wordIndex:exhibitionSpeechWordAt(this._loadedText||'',progress,this._loadedLanguage),playing:this.playing,progress});
    },
    async sync({ focused = false, advance = false } = {}) {
      if (!this._history) return;
      const audio = this.$refs.audio;
      if (!this.enabled || !this.shareId || document.hidden) { this.pause(); return; }
      if (this.busy || this.travelling || !this.arrived) return;
      // Focus changes queue a destination. Only an explicit Listen here action
      // interrupts the recording. Pause and replay refer to what is being heard.
      if (!focused && (this.playing || this.waiting)) return;
      const resumeLoaded = !focused && !advance && this.loadedKey && this._loadedLanguage === this.language
        && !this._history.progress(this._loadedCue, this._loadedLanguage).complete;
      const cue = resumeLoaded ? this._loadedCue : this.cue;
      // The guide stays armed between works, even when the visitor has not
      // reached the next cue yet. Finishing a recording is not a user pause.
      if (!cue || this._history.progress(cue, this.language).complete) return;
      const key = `${this.shareId}/${this.language}/${cue.key}`;
      if (this.loadedKey !== key) {
        if (this._loadedCue) this._history.remember(this._loadedCue, this._loadedLanguage, audio.currentTime || 0);
        this._token = (this._token || 0) + 1;
        this._loadedCue = cue; this._loadedLanguage = this.language; this.loadedKey = key; this._loadedText = this.text;
        const query = new URLSearchParams();
        if (this.language) query.set('language', this.language);
        if (cue.part) query.set('part', cue.part);
        audio.src = `${(process.env.VUE_APP_EXHIBITION_AUDIO_ENDPOINT || askEndpoints()[0]).replace(/\/$/, '')}/exhibition-audio/${encodeURIComponent(this.shareId)}/${cue.section}?${query}`;
      }
      this.error = false; this.waiting = true;
      const token = this._token || 0;
      window.dispatchEvent(new CustomEvent('view-summary-play', { detail: this }));
      try { await audio.play(); } catch { if (token === this._token && this.enabled) this.failed(); }
    },
    ended() {
      const cue = this._loadedCue;
      if (!cue) return;
      this._history.finish(cue, this._loadedLanguage); this.reportProgress(); this.pause();
      if (!this.enabled) return;
      if (cue.key === this.cue?.key) this.$emit('complete', cue.key);
      this.$nextTick(() => this.sync({ advance: true }));
    },
    failed() {
      if (!this.$refs.audio?.getAttribute('src')) return;
      this.pause(); this.error = true; this.loadedKey = '';
    },
  },
};
</script>

<style>
.exhibition-audio { display: flex; align-items: center; gap: 8px; position: relative; color: var(--ex-muted); }
.exhibition-audio button { appearance: none; border: 0; background: none; color: inherit; font: 12px/1.3 "Quattrocento Sans", sans-serif; display: flex; align-items: center; gap: 7px; padding: 4px 0; min-height: 28px; white-space: nowrap; cursor: var(--site-interactive-cursor); }
.exhibition-audio button:focus-visible { outline: 1px solid currentColor; outline-offset: 4px; }
.exhibition-audio button:disabled { opacity: .4; }
.exhibition-audio button:hover, .exhibition-audio.is-enabled { color: var(--ex-ink); }
.exhibition-audio svg { fill: none; stroke: currentColor; stroke-width: 1.25; stroke-linecap: round; stroke-linejoin: round; }
.exhibition-audio-symbol { width: 19px; height: 19px; flex: none; }
.exhibition-audio-state { width: 12px; height: 12px; display: grid; place-items: center; }
.exhibition-audio-state svg { width: 12px; height: 12px; }
.exhibition-audio-state circle { fill: currentColor; stroke: none; }
.exhibition-audio-state.is-waiting { animation: exhibition-audio-pulse 1s ease-in-out infinite alternate; }
.exhibition-audio-replay { width: 20px; }
.exhibition-audio-replay svg { width: 16px; height: 16px; }
.exhibition-audio .exhibition-audio-here { position: absolute; bottom: calc(100% + 10px); left: 50%; transform: translateX(-50%); padding: 8px 13px; border: 1px solid color-mix(in srgb, var(--ex-ink) 18%, transparent); border-radius: 3px; color: var(--ex-ink); background: color-mix(in srgb, var(--ex-paper, #f5f2eb) 94%, transparent); box-shadow: 0 3px 16px #00000008; font-size: 12px; gap: 10px; }
.exhibition-audio .exhibition-audio-here svg { width: 15px; height: 15px; transition: transform 180ms ease; }
.exhibition-audio .exhibition-audio-here:hover svg { transform: translateX(2px); }
.exhibition-audio-error { position: absolute; bottom: 100%; left: 0; font-size: 11px; white-space: nowrap; }
@keyframes exhibition-audio-pulse { to { opacity: .25; } }
@media (prefers-reduced-motion: reduce) { .exhibition-audio-state.is-waiting { animation: none; } }
</style>
